INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Jebakan Phishing Ada di Mana-mana$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bayangkan menerima email yang tampak dari bank, meminta Anda mengklik tautan dan memasukkan kata sandi karena "akun akan diblokir". Satu klik saja bisa membuat seluruh tabungan raib. Itulah phishing: penipuan yang menyamar sebagai pihak terpercaya untuk mencuri data pribadi, kata sandi, dan uang Anda. Di Indonesia, kasus phishing lewat SMS, WhatsApp, dan email terus meningkat setiap tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Phishing?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Phishing adalah teknik penipuan siber dengan menyamar sebagai lembaga resmi (bank, e-commerce, instansi pemerintah) melalui email, SMS, atau pesan chat. Korban diarahkan ke situs palsu yang mirip aslinya, lalu diminta memasukkan data login atau kode OTP. Ada juga spear phishing (menarget orang tertentu dengan data pribadi yang sudah dikumpulkan) dan vishing (phishing lewat telepon suara).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat: Persenjataan Anti Phishing$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Peramban modern dengan proteksi phishing bawaan (Chrome, Firefox, Edge)$$, $$Aplikasi autentikator untuk verifikasi dua langkah (2FA)$$, $$Manajer kata sandi agar tidak perlu mengetik manual di situs mencurigakan$$, $$Antivirus dengan fitur anti-phishing$$, $$Alamat email resmi bank/instansi yang tersimpan, bukan dari pesan masuk$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Cara Mengenali dan Menghindari Phishing$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Periksa pengirim: alamat email palsu sering mirip tapi ada typo, misalnya bank-aman.palsu.com$$, $$Jangan klik tautan dari pesan: buka aplikasi atau situs resmi secara manual$$, $$Curigai pesan yang mendesak: "segera", "akun diblokir", "hadiah" adalah ciri khas phishing$$, $$Periksa URL: pastikan ada gembok dan nama domain persis, bukan ejaan mirip$$, $$Jangan pernah berikan kode OTP kepada siapa pun, termasuk yang mengaku petugas bank$$, $$Aktifkan 2FA di semua akun penting: email, perbankan, media sosial$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Jika Sudah Terlanjur Kena$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jika Anda sudah memasukkan data di situs palsu, segera ganti kata sandi dari perangkat yang aman, aktifkan 2FA, hubungi bank untuk memblokir transaksi mencurigakan, dan laporkan ke pihak berwenang. Jangan panik, tapi bertindak cepat: setiap menit berarti. Simpan bukti pesan phishing untuk laporan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian: Checklist Keamanan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Semua akun penting sudah memakai kata sandi unik dan 2FA$$, $$Keluarga (terutama orang tua) sudah diedukasi tentang modus phishing$$, $$Tautan dari pesan asing tidak pernah diklik langsung$$, $$Nomor call center resmi bank tersimpan untuk verifikasi cepat$$, $$Laporan phishing dikirim ke kanal resmi agar pelaku bisa ditindak$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Mata Tiba-tiba Sakit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bangun tidur mata merah dan berair, atau mata terasa mengganjal setelah terkena debu di jalan. Sakit mata memang mengganggu aktivitas, dan banyak orang langsung panik lalu menguceknya atau meneteskan obat sembarangan. Padahal, penanganan pertama yang benar bisa mencegah kondisi memburuk. Catatan: artikel ini informasi umum, bukan pengganti nasihat medis. Konsultasikan ke dokter bila ragu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab Umum Sakit Mata$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Sakit mata ringan umumnya disebabkan iritasi debu atau asap, kelelahan, mata kering karena terlalu lama menatap layar, alergi, atau konjungtivitis (radang selaput mata) akibat virus/bakteri. Kelilipan benda asing kecil juga sering terjadi. Yang perlu diwaspadai: cedera benda tajam, bahan kimia masuk mata, atau nyeri hebat dengan gangguan penglihatan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Air bersih matang atau larutan saline steril$$, $$Kain bersih atau handuk lembut$$, $$Kompres dingin (es dibungkus kain)$$, $$Obat tetes mata air mata buatan (bila tersedia)$$, $$Kacamata hitam untuk perlindungan dari cahaya$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Pertolongan Pertama yang Benar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Cuci tangan dengan sabun sebelum menyentuh area mata$$, $$Jangan mengucek mata: berkedip beberapa kali untuk membantu mengeluarkan benda asing$$, $$Bilas mata dengan air bersih mengalir selama beberapa menit bila terkena debu atau iritan ringan$$, $$Kompres dingin 10-15 menit untuk mengurangi bengkak dan gatal$$, $$Istirahatkan mata dari layar dan cahaya terang$$, $$Lepas lensa kontak bila memakainya, ganti dengan kacamata sementara$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kesalahan yang Sering Dilakukan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Mengucek mata keras-keras bisa melukai kornea. Meneteskan obat mata steroid tanpa resep dokter berisiko memperparah infeksi. Memakai obat tetes mata milik orang lain juga berbahaya karena bisa menularkan infeksi. Hindari meneteskan getah tanaman atau ramuan tak jelas ke mata.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian: Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Nyeri hebat atau penglihatan kabur/menurun$$, $$Mata terkena bahan kimia: bilas lalu segera ke IGD$$, $$Keluar nanah kental berwarna kuning-hijau$$, $$Mata merah tidak membaik setelah 2-3 hari$$, $$Ada riwayat cedera benda tajam atau pukulan$$, $$Bila ragu, konsultasikan ke dokter mata atau fasilitas kesehatan terdekat$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Suku Toraja?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Toraja mendiami dataran tinggi Tana Toraja di Sulawesi Selatan. Mereka terkenal dengan budaya yang sangat menghormati leluhur, arsitektur rumah adat tongkonan yang khas dengan atap melengkung seperti perahu, dan upacara pemakaman megah bernama Rambu Solo.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Filosofi: Kematian Bukan Akhir$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bagi masyarakat Toraja, kematian bukan akhir melainkan perpindahan ke alam puya (dunia arwah). Orang yang meninggal dianggap "sakit" (toma kula) dan tetap diperlakukan seperti masih hidup: diberi makan, diajak bicara, hingga upacara pemakaman dilaksanakan. Keyakinan ini disebut Aluk Todolo, kepercayaan asli sebelum masuknya agama Kristen dan Islam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Upacara Rambu Solo$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Rambu Solo adalah upacara pemakaman adat yang bisa berlangsung berhari-hari dengan ratusan hingga ribuan tamu. Rangkaiannya meliputi penyembelihan kerbau dan babi (jumlahnya menunjukkan status sosial almarhum), tarian, dan arak-arakan peti. Biaya upacara bisa sangat besar sehingga keluarga menabung bertahun-tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tongkonan: Rumah Leluhur$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Tongkonan adalah rumah adat sekaligus pusat kehidupan keluarga besar. Atapnya melengkung tinggi menyerupai perahu, dindingnya dihiasi ukiran khas Toraja yang penuh makna. Di halaman tongkonan terdapat lumbung padi (alang) dan kuburan tebing dengan patung tau-tau yang menggambarkan wajah almarhum.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Rambu Tuka: Upacara Kehidupan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Selain Rambu Solo (upacara duka), ada Rambu Tuka: upacara syukuran untuk kehidupan seperti pernikahan, panen, dan peresmian tongkonan baru. Keduanya menunjukkan keseimbangan pandangan Toraja antara menghormati kematian dan merayakan kehidupan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Platina?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Platina (simbol Pt, nomor atom 78) adalah logam mulia berwarna putih keperakan yang sangat langka: jumlahnya di kerak bumi sekitar 30 kali lebih sedikit daripada emas. Ia termasuk golongan logam platina bersama paladium, rodium, iridium, osmium, dan rutenium.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat Istimewa Platina$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Platina sangat tahan korosi dan tidak bereaksi dengan sebagian besar asam, bahkan pada suhu tinggi. Titik leburnya 1.768 derajat Celsius, jauh di atas emas. Ia juga merupakan katalis hebat: mempercepat reaksi kimia tanpa ikut habis. Sifat uletnya memungkinkan dibentuk menjadi kawat sangat tipis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Sejarah Singkat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Suku asli Amerika Selatan sudah memakai platina jauh sebelum bangsa Eropa mengenalnya. Bangsa Spanyol awalnya menganggapnya "perak kecil" (platina berarti perak kecil dalam bahasa Spanyol) dan kurang berharga. Baru pada abad ke-18 para ilmuwan menyadari keistimewaannya, dan kini Afrika Selatan menjadi penghasil sekitar 70 persen platina dunia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan dalam Industri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Sekitar 40 persen platina dunia dipakai untuk catalytic converter pada knalpot mobil yang mengubah gas beracun menjadi gas lebih aman. Ia juga dipakai dalam industri kimia, peralatan laboratorium tahan panas, elektrode, dan sel bahan bakar hidrogen yang sedang berkembang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Platina dalam Perhiasan dan Investasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Karena langka dan tidak mudah pudar, platina menjadi bahan perhiasan premium, sering untuk cincin kawin mewah. Harganya umumnya di atas emas, meski bisa berfluktuasi mengikuti permintaan industri otomotif. Batangan dan koin platina juga menjadi instrumen investasi logam mulia.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu menyebutkan jenis-jenis manusia purba di Indonesia, menjelaskan ciri-cirinya, dan mendeskripsikan cara hidup mereka pada zaman prasejarah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Meganthropus Palaeojavanicus$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Meganthropus berarti "manusia raksasa dari Jawa". Fosilnya ditemukan oleh von Koenigswald di Sangiran, Jawa Tengah, pada 1941. Ciri-cirinya: rahang besar dan kuat, tulang pipi tebal, tonjolan kening menyolok, dan diperkirakan hidup sekitar 1-2 juta tahun lalu dengan cara berburu dan mengumpulkan makanan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pithecanthropus Erectus$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Ditemukan oleh Eugene Dubois di Trinil, Ngawi, Jawa Timur, pada 1891. Artinya "manusia kera yang berjalan tegak". Ciri-cirinya: volume otak sekitar 900 cc, tinggi sekitar 165-170 cm, berjalan tegak, dan sudah mengenal api serta membuat alat dari batu dan tulang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Homo Sapiens Awal di Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Homo sapiens berarti "manusia cerdas". Di Indonesia ditemukan jenis Homo soloensis (Ngandong) dan Homo wajakensis (Wajak, Tulungagung). Mereka memiliki volume otak sekitar 1.000-1.200 cc, wajah tidak terlalu menonjol, dan sudah hidup berkelompok dengan pembagian tugas.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Cara Hidup Manusia Purba$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Manusia purba hidup dengan berburu hewan dan meramu tumbuhan (food gathering). Mereka tinggal di gua atau dekat sumber air, membuat peralatan dari batu (kapak genggam, flakes), dan belum mengenal pertanian menetap. Kehidupan mereka sangat bergantung pada alam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Sebutkan tiga jenis manusia purba yang ditemukan di Indonesia beserta lokasi penemuannya!$$, $$Jelaskan perbedaan ciri fisik Pithecanthropus erectus dan Homo sapiens!$$, $$Mengapa manusia purba hidup berpindah-pindah (nomaden)? Jelaskan alasannya!$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 12, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 13, jsonb_build_object('items', ARRAY[$$Meganthropus palaeojavanicus (Sangiran), Pithecanthropus erectus (Trinil), Homo soloensis (Ngandong)/Homo wajakensis (Wajak)$$, $$Pithecanthropus: volume otak sekitar 900 cc, kening menonjol, rahang besar; Homo sapiens: volume otak 1.000-1.400 cc, wajah lebih rata, lebih cerdas$$, $$Karena bergantung pada ketersediaan makanan dari alam; bila sumber makanan habis, mereka pindah mencari daerah baru yang subur$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Halo adik-adik! Setelah belajar materi ini, kalian bisa menyebutkan siapa saja anggota keluarga, tahu tugas masing-masing, dan tahu cara menyayangi keluarga. Yuk belajar bersama!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Siapa Saja Anggota Keluargaku?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Keluarga inti terdiri dari ayah, ibu, dan anak. Ada juga keluarga besar: kakek, nenek, paman, bibi, dan sepupu. Setiap keluarga berbeda-beda, ada yang tinggal bersama kakek nenek, ada juga yang hanya ayah, ibu, dan anak. Semua sama-sama keluarga yang saling menyayangi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Tugas Ayah dan Ibu$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Ayah bekerja mencari nafkah untuk keluarga, misalnya menjadi guru, petani, atau pedagang. Ibu mengurus rumah dan anak-anak, ada juga ibu yang bekerja. Ayah dan ibu sama-sama menyayangi anak-anaknya dan bekerja sama mengurus keluarga.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tugasku sebagai Anak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Sebagai anak, tugasmu adalah belajar dengan rajin, membantu orang tua semampumu, dan bersikap baik kepada kakak atau adik. Contohnya: merapikan mainan sendiri, membantu ibu menyapu, dan tidak bertengkar dengan saudara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Menyayangi Keluarga$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kita bisa menunjukkan sayang kepada keluarga dengan cara sederhana: mengucapkan salam saat pergi dan pulang, membantu pekerjaan rumah, mendoakan orang tua, dan berkata jujur. Keluarga yang saling menyayangi akan hidup rukun dan bahagia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Sebutkan anggota keluarga intimu!$$, $$Apa pekerjaan ayah dan ibumu?$$, $$Sebutkan dua contoh cara membantu orang tua di rumah!$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 12, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 13, jsonb_build_object('items', ARRAY[$$Ayah, ibu, dan anak (kakak/adik bila ada)$$, $$Jawaban sesuai kondisi masing-masing, misalnya ayah petani dan ibu pedagang$$, $$Merapikan mainan, membantu menyapu, mencuci piring sendiri, dan contoh baik lainnya$$]));
